final class PooledConnection {
    private let pool: Pool
    let conn: Conn
    init(_ pool: Pool) { self.pool = pool; conn = pool.checkout() }
    deinit { pool.checkin(conn) }        // hand back when the last ref dies
}

let lease = PooledConnection(pool)       // released at end of scope
use(lease.conn)
